# ! [doc = " This file provides API for compiler consumers."] use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: FxHashMap ; use rustc_hir :: def_id :: LocalDefId ; use rustc_index :: IndexVec ; use rustc_middle :: bug ; use rustc_middle :: mir :: { Body , Promoted } ; use rustc_middle :: ty :: TyCtxt ; pub use super :: borrow_set :: { BorrowData , BorrowSet , TwoPhaseActivation } ; pub use super :: constraints :: OutlivesConstraint ; pub use super :: dataflow :: { BorrowIndex , Borrows , calculate_borrows_out_of_scope_at_location } ; pub use super :: place_ext :: PlaceExt ; pub use super :: places_conflict :: { PlaceConflictBias , places_conflict } ; pub use super :: polonius :: legacy :: { PoloniusFacts as PoloniusInput , PoloniusLocationTable , PoloniusOutput , PoloniusRegionVid , RichLocation , RustcFacts , } ; pub use super :: region_infer :: RegionInferenceContext ; use crate :: BorrowCheckRootCtxt ; #[doc = " Struct used during mir borrowck to collect bodies with facts for a typeck root and all"] #[doc = " its nested bodies."] pub (crate) struct BorrowckConsumer < 'tcx > { options : ConsumerOptions , bodies : FxHashMap < LocalDefId , BodyWithBorrowckFacts < 'tcx > > , } impl < 'tcx > BorrowckConsumer < 'tcx > { pub (crate) fn new (options : ConsumerOptions) -> Self { Self { options , bodies : Default :: default () } } pub (crate) fn insert_body (& mut self , def_id : LocalDefId , body : BodyWithBorrowckFacts < 'tcx >) { if self . bodies . insert (def_id , body) . is_some () { bug ! ("unexpected previous body for {def_id:?}") ; } } #[doc = " Should the Polonius input facts be computed?"] pub (crate) fn polonius_input (& self) -> bool { matches ! (self . options , ConsumerOptions :: PoloniusInputFacts | ConsumerOptions :: PoloniusOutputFacts) } #[doc = " Should we run Polonius and collect the output facts?"] pub (crate) fn polonius_output (& self) -> bool { matches ! (self . options , ConsumerOptions :: PoloniusOutputFacts) } } #[doc = " Options determining the output behavior of [`get_bodies_with_borrowck_facts`]."] #[doc = ""] #[doc = " If executing under `-Z polonius` the choice here has no effect, and everything as if"] #[doc = " [`PoloniusOutputFacts`](ConsumerOptions::PoloniusOutputFacts) had been selected"] #[doc = " will be retrieved."] #[derive (Debug , Copy , Clone)] pub enum ConsumerOptions { #[doc = " Retrieve the [`Body`] along with the [`BorrowSet`]"] #[doc = " and [`RegionInferenceContext`]. If you would like the body only, use"] #[doc = " [`TyCtxt::mir_promoted`]."] #[doc = ""] #[doc = " These can be used in conjunction with [`calculate_borrows_out_of_scope_at_location`]."] RegionInferenceContext , #[doc = " The recommended option. Retrieves the maximal amount of information"] #[doc = " without significant slowdowns."] #[doc = ""] #[doc = " Implies [`RegionInferenceContext`](ConsumerOptions::RegionInferenceContext),"] #[doc = " and additionally retrieve the [`PoloniusLocationTable`] and [`PoloniusInput`] that"] #[doc = " would be given to Polonius. Critically, this does not run Polonius, which"] #[doc = " one may want to avoid due to performance issues on large bodies."] PoloniusInputFacts , #[doc = " Implies [`PoloniusInputFacts`](ConsumerOptions::PoloniusInputFacts),"] #[doc = " and additionally runs Polonius to calculate the [`PoloniusOutput`]."] PoloniusOutputFacts , } #[doc = " A `Body` with information computed by the borrow checker. This struct is"] #[doc = " intended to be consumed by compiler consumers."] #[doc = ""] #[doc = " We need to include the MIR body here because the region identifiers must"] #[doc = " match the ones in the Polonius facts."] pub struct BodyWithBorrowckFacts < 'tcx > { #[doc = " A mir body that contains region identifiers."] pub body : Body < 'tcx > , #[doc = " The mir bodies of promoteds."] pub promoted : IndexVec < Promoted , Body < 'tcx > > , #[doc = " The set of borrows occurring in `body` with data about them."] pub borrow_set : BorrowSet < 'tcx > , #[doc = " Context generated during borrowck, intended to be passed to"] #[doc = " [`calculate_borrows_out_of_scope_at_location`]."] pub region_inference_context : RegionInferenceContext < 'tcx > , #[doc = " The table that maps Polonius points to locations in the table."] #[doc = " Populated when using [`ConsumerOptions::PoloniusInputFacts`]"] #[doc = " or [`ConsumerOptions::PoloniusOutputFacts`]."] pub location_table : Option < PoloniusLocationTable > , #[doc = " Polonius input facts."] #[doc = " Populated when using [`ConsumerOptions::PoloniusInputFacts`]"] #[doc = " or [`ConsumerOptions::PoloniusOutputFacts`]."] pub input_facts : Option < Box < PoloniusInput > > , #[doc = " Polonius output facts. Populated when using"] #[doc = " [`ConsumerOptions::PoloniusOutputFacts`]."] pub output_facts : Option < Box < PoloniusOutput > > , } #[doc = " This function computes borrowck facts for the given def id and all its nested bodies."] #[doc = " It must be called with a typeck root which will then borrowck all nested bodies as well."] #[doc = " The [`ConsumerOptions`] determine which facts are returned. This function makes a copy"] #[doc = " of the bodies because it needs to regenerate the region identifiers. It should never be"] #[doc = " invoked during a typical compilation session due to the unnecessary overhead of"] #[doc = " returning [`BodyWithBorrowckFacts`]."] #[doc = ""] #[doc = " Note:"] #[doc = " *   This function will panic if the required bodies were already stolen. This"] #[doc = "     can, for example, happen when requesting a body of a `const` function"] #[doc = "     because they are evaluated during typechecking. The panic can be avoided"] #[doc = "     by overriding the `mir_borrowck` query. You can find a complete example"] #[doc = "     that shows how to do this at `tests/ui-fulldeps/obtain-borrowck.rs`."] #[doc = ""] #[doc = " *   Polonius is highly unstable, so expect regular changes in its signature or other details."] pub fn get_bodies_with_borrowck_facts (tcx : TyCtxt < '_ > , root_def_id : LocalDefId , options : ConsumerOptions ,) -> FxHashMap < LocalDefId , BodyWithBorrowckFacts < '_ > > { let mut root_cx = BorrowCheckRootCtxt :: new (tcx , root_def_id , Some (BorrowckConsumer :: new (options))) ; root_cx . do_mir_borrowck () ; root_cx . consumer . unwrap () . bodies }